package communication;import cern.cmw.data.Data;import codec.ByteStreamDecoder;import codec.javatocmw.JavaToCMWData;import codec.javatolv.JavaDataSerialiser;import codec.javatolv.LVTypeDescriptorFactory;import jakarta.servlet.ServletException;import jakarta.servlet.ServletInputStream;import jakarta.servlet.http.HttpServlet;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import types.JavaDataContainer;import java.io.IOException;import java.io.PrintWriter;import java.util.Arrays;public class HTTPListener extends HttpServlet {        /**         * @param args         */        public static void main(String[] args) {        }        public void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {            ServletInputStream reader = request.getInputStream();            byte[] message = reader.readAllBytes();            ByteStreamDecoder byteStreamDecoder = new ByteStreamDecoder();            JavaDataContainer javaDataContainer = byteStreamDecoder.decode(message);            PrintWriter out = response.getWriter();            out.print("test");            byte [] data = JavaDataSerialiser.serialise(javaDataContainer);            byte[] desc = LVTypeDescriptorFactory.createTypeDescrptor(javaDataContainer);            out.println(Arrays.toString(desc));            out.println(Arrays.toString(data));        }    @Override    public void doGet(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {        doPost(req, resp);    }}